#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
int main(void) {
    const char *text = "12";
    char *end;
    errno = 0;
    long value = strtol(text, &end, 10);
    if (end == text || *end != '\0' || errno == ERANGE) { puts("invalid"); }
    else { printf("%ld\n", value); }
    return 0;
}

